// ---------------------------------------------------------------------
// lib/help-content.ts — Help Center single source of truth.
//
// Every article in /help is defined here. The `image` field points at a
// screenshot generated by `npm run help:shots`
// (scripts/capture-help-shots.mjs → public/help/shots/<id>.webp).
// If a screenshot file doesn't exist yet, <HelpImage> renders a styled
// placeholder frame instead — the site works before shots are captured.
//
// Search matches against title + keywords + summary + step text, so
// phrasing like "how do I report someone missing" finds the right topic.
// ---------------------------------------------------------------------

export type HelpCategory = "emergencies" | "citizen" | "gov" | "account";

export type HelpStep = {
  title: string;
  text: string;
};

export type HelpTopic = {
  id: string;
  title: string;
  category: HelpCategory;
  /** Extra search terms beyond the title. */
  keywords: string[];
  /** One-line answer shown on cards and search results. */
  summary: string;
  steps: HelpStep[];
  /** Screenshot path under /public (no leading slash duplication). */
  image: string;
  related: string[];
};

