/** Look up one topic, undefined when the slug doesn't exist. */
export function getHelpTopic(id: string): HelpTopic | undefined {
  return HELP_TOPICS.find((t) => t.id === id);
}

/** All topics in a category, config order. */
export function topicsByCategory(category: HelpCategory): HelpTopic[] {
  return HELP_TOPICS.filter((t) => t.category === category);
}

/** Client-side search across title, keywords, summary and step text. */
export function searchHelpTopics(query: string): HelpTopic[] {
  const q = query.trim().toLowerCase();
  if (!q) return HELP_TOPICS;
  const terms = q.split(/\s+/);
  return HELP_TOPICS.map((topic) => {
    const haystack = [
      topic.title,
      topic.summary,
      ...topic.keywords,
      ...topic.steps.flatMap((s) => [s.title, s.text]),
    ]
      .join(" ")
      .toLowerCase();
    const score = terms.reduce(
      (acc, term) => acc + (haystack.includes(term) ? 1 : 0),
      0,
    );
    return { topic, score };
  })
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score)
    .map(({ topic }) => topic);
}
